import subprocess, json, sys, threading, time, os, queue

class LSP:
    def __init__(self, args=None, cwd=None, env=None):
        e = dict(os.environ); e.update(env or {})
        self.p = subprocess.Popen(["/workspace/executable"]+(args or []),
            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=cwd, env=e)
        self.msgs = queue.Queue()
        self.errlines = []
        threading.Thread(target=self._read, daemon=True).start()
        threading.Thread(target=self._readerr, daemon=True).start()
        self.nid = 0
    def _read(self):
        f = self.p.stdout
        while True:
            hdr = b""
            while not hdr.endswith(b"\r\n\r\n"):
                c = f.read(1)
                if not c: return
                hdr += c
            n = 0
            for line in hdr.decode().split("\r\n"):
                if line.lower().startswith("content-length:"):
                    n = int(line.split(":")[1].strip())
            body = f.read(n)
            self.msgs.put(json.loads(body))
    def _readerr(self):
        for line in self.p.stderr:
            self.errlines.append(line.decode(errors="replace").rstrip())
    def send(self, obj):
        b = json.dumps(obj).encode()
        self.p.stdin.write(b"Content-Length: %d\r\n\r\n" % len(b) + b)
        self.p.stdin.flush()
    def req(self, method, params, id=None):
        self.nid += 1
        i = self.nid if id is None else id
        self.send({"jsonrpc":"2.0","id":i,"method":method,"params":params})
        return i
    def notify(self, method, params):
        self.send({"jsonrpc":"2.0","method":method,"params":params})
    def drain(self, t=1.0):
        out = []
        end = time.time()+t
        while time.time() < end:
            try: out.append(self.msgs.get(timeout=0.05))
            except queue.Empty: pass
        return out
    def kill(self): self.p.kill()
PYEOF
echo ok

