from lsp import LSP
import json, time, queue, threading, sys
t0=time.time()
def log(*a): print("%7.3f"%(time.time()-t0), *a); sys.stdout.flush()
l = LSP(["--stdio"], cwd="/tmp/ws")
stop=False
def mon():
    while not stop:
        try:
            m=l.msgs.get(timeout=0.05); log("MSG", json.dumps(m)[:300])
            if "id" in m and "method" in m: l.send({"jsonrpc":"2.0","id":m["id"],"result":None}); log("  replied")
        except queue.Empty: pass
def mone():
    while not stop:
        if l.errlines: log("ERR", l.errlines.pop(0))
        else: time.sleep(0.03)
threading.Thread(target=mon,daemon=True).start(); threading.Thread(target=mone,daemon=True).start()
log("send initialize")
l.req("initialize", {"processId":None,"rootUri":"file:///tmp/ws","capabilities":{"window":{"workDoneProgress":True}}})
time.sleep(2)
log("send initialized"); l.notify("initialized", {}); time.sleep(2)
src = open("/tmp/ws/src/main.rs").read()
log("send didOpen"); l.notify("textDocument/didOpen", {"textDocument":{"uri":"file:///tmp/ws/src/main.rs","languageId":"rust","version":1,"text":src}}); time.sleep(6)
log("send cursor"); l.req("rustowl/cursor", {"position":{"line":2,"character":9},"document":{"uri":"file:///tmp/ws/src/main.rs"}}); time.sleep(3)
log("send cursor2"); l.req("rustowl/cursor", {"position":{"line":2,"character":9},"document":{"uri":"file:///tmp/ws/src/main.rs"}}); time.sleep(3)
stop=True; l.kill()
