from lsp import LSP
import json, time, queue, threading, sys
t0=time.time()
def log(*a): print("%7.3f"%(time.time()-t0), *a); sys.stdout.flush()
def start(root):
    global t0
    t0=time.time()
    l = LSP(["--stdio"], cwd="/tmp/ws"); st=[False]
    def mon():
        while not st[0]:
            try:
                m=l.msgs.get(timeout=0.05); log("MSG", json.dumps(m)[:250])
                if "id" in m and "method" in m: l.send({"jsonrpc":"2.0","id":m["id"],"result":None})
            except queue.Empty: pass
    def mone():
        while not st[0]:
            if l.errlines: log("ERR", l.errlines.pop(0))
            else: time.sleep(0.02)
    threading.Thread(target=mon,daemon=True).start(); threading.Thread(target=mone,daemon=True).start()
    l.send({"jsonrpc":"2.0","id":1,"method":"initialize","params":{"rootUri":root,"capabilities":{"window":{"workDoneProgress":True}}}}); time.sleep(1)
    l.notify("initialized",{}); time.sleep(0.5)
    return l, st
print("###### rootUri = file .rs")
l,st = start("file:///tmp/ws/src/main.rs")
src=open("/tmp/ws/src/main.rs").read()
log("didOpen"); l.notify("textDocument/didOpen", {"textDocument":{"uri":"file:///tmp/ws/src/main.rs","languageId":"rust","version":1,"text":src}}); time.sleep(3)
log("cursor"); l.req("rustowl/cursor", {"position":{"line":2,"character":9},"document":{"uri":"file:///tmp/ws/src/main.rs"}}); time.sleep(2)
log("didChange"); l.notify("textDocument/didChange", {"textDocument":{"uri":"file:///tmp/ws/src/main.rs","version":2},"contentChanges":[{"text":src+"\n"}]}); time.sleep(3)
log("didSave"); l.notify("textDocument/didSave", {"textDocument":{"uri":"file:///tmp/ws/src/main.rs"}}); time.sleep(3)
st[0]=True; l.kill()
PYEOF
